-- Prompts probados en local entre 2026-11-21 y 2026-11-23 (antes solo en archivos SQL locales
-- de Claude Artifacts): recall v2, reagendar v1–v3 (reschedule_reminder + widen_if_empty) y el campo
-- moveExisting del clasificador (D-030).
-- Seguro de correr dos veces: cada cambio se salta si ya está aplicado (marcador). Si el texto a
-- reemplazar no existe, la migración FALLA y no deja el prompt a medias.
do $mig$
declare p text;
begin
  select prompt into p from public.system_prompts where code = 'ai_chat_system' and is_active for update;
  if p is null then raise exception 'system_prompts: no hay prompt activo %', 'ai_chat_system'; end if;
  -- recall v2
  if position($p$AND THE SWEEP IS ONE recall CALL$p$ in p) = 0 then
    if position($p$- LOOKING SOMETHING UP IS A SWEEP, NOT ONE CALL. The advisor asks vaguely on purpose — "tengo algo de diagnostico con Alejandra?", "a quien le dije que le daria una sesion de diagnostico?", "cuando tengo lo de control de gastos?" — because they do not remember which drawer it went into, and making them remember is the opposite of what this product is for. Whenever the question names a TOPIC instead of a record, what they are after can live in four places and the question does not tell you which: reminders (search_reminders), commitments (get_commitments with its query parameter), the client's notes (search_contact_notes), ingested documents (search_knowledge). Call EVERY one that could hold it, in the SAME turn, before you say anything. If they named a person, resolve them with search_contact first and pass contact_id wherever the tool accepts one.$p$ in p) = 0 then raise exception 'system_prompts ai_chat_system (recall v2): no se encontró el texto a reemplazar; el prompt de este ambiente difiere del esperado'; end if;
    p := replace(p, $p$- LOOKING SOMETHING UP IS A SWEEP, NOT ONE CALL. The advisor asks vaguely on purpose — "tengo algo de diagnostico con Alejandra?", "a quien le dije que le daria una sesion de diagnostico?", "cuando tengo lo de control de gastos?" — because they do not remember which drawer it went into, and making them remember is the opposite of what this product is for. Whenever the question names a TOPIC instead of a record, what they are after can live in four places and the question does not tell you which: reminders (search_reminders), commitments (get_commitments with its query parameter), the client's notes (search_contact_notes), ingested documents (search_knowledge). Call EVERY one that could hold it, in the SAME turn, before you say anything. If they named a person, resolve them with search_contact first and pass contact_id wherever the tool accepts one.$p$, $p$- LOOKING SOMETHING UP IS A SWEEP, AND THE SWEEP IS ONE recall CALL. The advisor asks vaguely on purpose — "tengo algo de diagnostico con Alejandra?", "a quien le dije que le daria una sesion de diagnostico?", "cuando tengo lo de control de gastos?" — because they do not remember which drawer it went into, and making them remember is the opposite of what this product is for. Whenever the question names a TOPIC instead of a record, or asks for everything about a person or an insurer, call `recall` ONCE: it searches contacts, policies, reminders, commitments, notes and documents in parallel and returns six separate groups. If they named a person, resolve them with search_contact first and pass contact_id. If the question names a concrete record — "summary of Julio's GMM policy", "what does Maria's reminder say", "my payments this week" — use the direct skill for that record instead, never recall. When a group has moreAvailable true and the advisor wants more, call recall again with the next page, the same query and the searchId you received. When a document has moreInDocument true and the advisor wants more of THAT document, call recall again with note_id (its noteId) + the same query + the searchId.$p$);
    if position($p$An empty search_knowledge means the DOCUMENTS do not mention it; it says nothing at all about their reminders or their commitments. You may only say there is nothing after every source above came back empty$p$ in p) = 0 then raise exception 'system_prompts ai_chat_system (recall v2): no se encontró el texto a reemplazar; el prompt de este ambiente difiere del esperado'; end if;
    p := replace(p, $p$An empty search_knowledge means the DOCUMENTS do not mention it; it says nothing at all about their reminders or their commitments. You may only say there is nothing after every source above came back empty$p$, $p$An empty search_knowledge, or one empty recall group, means only THAT source does not mention it; it says nothing at all about the other groups. You may only say there is nothing after every group came back empty$p$);
    if position($p$search_contact_notes, search_policy_notes, or search_reminder_notes to write your answer$p$ in p) = 0 then raise exception 'system_prompts ai_chat_system (recall v2): no se encontró el texto a reemplazar; el prompt de este ambiente difiere del esperado'; end if;
    p := replace(p, $p$search_contact_notes, search_policy_notes, or search_reminder_notes to write your answer$p$, $p$search_contact_notes, search_policy_notes, search_reminder_notes, or recall (groups "notes" and "documents") to write your answer$p$);
  end if;
  -- reagendar v1
  if position($p$RESCHEDULING MOVES WHAT ALREADY EXISTS$p$ in p) = 0 then
    if position($p$- ONE ANSWER PER TURN$p$ in p) = 0 then raise exception 'system_prompts ai_chat_system (reagendar v1): no se encontró el texto a reemplazar; el prompt de este ambiente difiere del esperado'; end if;
    p := replace(p, $p$- ONE ANSWER PER TURN$p$, $p$- RESCHEDULING MOVES WHAT ALREADY EXISTS. "reagendalo", "muevelo a manana", "cambiala para el lunes", "pasala a las 5", "no me puede ver hoy, que sea manana" all refer to an appointment or reminder the advisor ALREADY HAS. First find it: resolve the person with search_contact, then search_reminders (with contact_id) or get_upcoming_reminders for the day they mention. If you find it, call update_reminder on THAT record with the new date, and KEEP its original time unless they gave a new one. NEVER create a new reminder to reschedule: that leaves two appointments and the old one keeps ringing. If you find NOTHING to move, do not create anything: say you found no appointment with that person for that day and ask whether they want you to schedule one, and at what time if they did not say. Never invent an hour.
- ONE ANSWER PER TURN$p$);
  end if;
  -- reagendar v2
  if position($p$call reschedule_reminder with ITS id$p$ in p) = 0 then
    if position($p$If you find it, call update_reminder on THAT record with the new date, and KEEP its original time unless they gave a new one.$p$ in p) = 0 then raise exception 'system_prompts ai_chat_system (reagendar v2): no se encontró el texto a reemplazar; el prompt de este ambiente difiere del esperado'; end if;
    p := replace(p, $p$If you find it, call update_reminder on THAT record with the new date, and KEEP its original time unless they gave a new one.$p$, $p$If you find it, call reschedule_reminder with ITS id and the new date; pass new_time ONLY if they gave a new hour (the tool keeps the original time by itself).$p$);
  end if;
  -- reagendar v3
  if position($p$widen_if_empty: true (it already searches every date$p$ in p) = 0 then
    if position($p$First find it: resolve the person with search_contact, then search_reminders (with contact_id) or get_upcoming_reminders for the day they mention.$p$ in p) = 0 then raise exception 'system_prompts ai_chat_system (reagendar v3): no se encontró el texto a reemplazar; el prompt de este ambiente difiere del esperado'; end if;
    p := replace(p, $p$First find it: resolve the person with search_contact, then search_reminders (with contact_id) or get_upcoming_reminders for the day they mention.$p$, $p$First find it: resolve the person with search_contact, then make ONE call to get_upcoming_reminders with contact_id and widen_if_empty: true (it already searches every date, including overdue). If it comes back widened with no reminders, there is nothing to move: do not search reminders or commitments again; ask. If the only appointment you found is on a different day than the one they mentioned (it came back widened), do NOT move it yet: tell them when it is and ask whether that is the one to move.$p$);
  end if;
  update public.system_prompts set prompt = p, updated_at = now() where code = 'ai_chat_system' and is_active;

  select prompt into p from public.system_prompts where code = 'message_classifier_system' and is_active for update;
  if p is null then raise exception 'system_prompts: no hay prompt activo %', 'message_classifier_system'; end if;
  -- clasificador moveExisting
  if position($p$"moveExisting": false$p$ in p) = 0 then
    if position($p$Respond ONLY with a JSON format: { "domains": ["domain1", "domain2"], "language": "Spanish" }$p$ in p) = 0 then raise exception 'system_prompts message_classifier_system (clasificador moveExisting): no se encontró el texto a reemplazar; el prompt de este ambiente difiere del esperado'; end if;
    p := replace(p, $p$Respond ONLY with a JSON format: { "domains": ["domain1", "domain2"], "language": "Spanish" }$p$, $p$Also report "moveExisting": true when the advisor asks to move, reschedule, postpone or change the time of something that ALREADY exists (an appointment or reminder); false for anything else, including creating a new one or giving a time for a new one. Examples: "Patricia me dijo que hoy no me puede ver, que la reagende mañana" -> true; "pasa mi cita con Luis para el viernes" -> true; "move my 5pm call to Monday" -> true; "agéndame una llamada con Rosa mañana a las 10" -> false; "schedule a meeting with Ana on Friday" -> false; "a las 10" (answering a time question) -> false.

Respond ONLY with a JSON format: { "domains": ["domain1", "domain2"], "language": "Spanish", "moveExisting": false }$p$);
  end if;
  update public.system_prompts set prompt = p, updated_at = now() where code = 'message_classifier_system' and is_active;
end
$mig$;
